{-| @Pudu.Backend.Emit — [[Core IR]] to one deterministic C11 translation
    unit.

    Emission is a pure function of the core module, the program's sources, and
    the compiler version: the same program always produces the same bytes. The
    runtime prologue, the diagnostic site table, and the functions are written
    in a fixed order; identifiers are derived from local identities, never
    from source names; and every checked operation carries the site the
    interpreter would have reported, baked from the same span, excerpt
    geometry, and [[Diagnostic Arithmetic]] text.
-}
module Pudu.Backend.Emit
  ( emitProgram
  ) where

import qualified Data.ByteString as ByteString
import Data.Char (ord)
import Data.Int (Int64)
import qualified Data.Set as Set
import Data.Text (Text)
import qualified Data.Text as Text
import qualified Data.Text.Encoding as Text

import Pudu.Backend.Runtime (RuntimePart (..), runtimeParts)
import Pudu.Core
import Pudu.Diagnostic.Arithmetic
  ( CheckedOperation (..)
  , divideByZeroCode
  , divideByZeroMessage
  , overflowCode
  , overflowHelp
  , overflowMessage
  )
import Pudu.Diagnostic.Render (Excerpt (..), excerptGeometry)
import Pudu.IntegerLiteral (IntegerKind (..))
import Pudu.Source
  ( Position (..)
  , Source
  , Span
  , offsetPosition
  , sourceName
  , spanSource
  , spanStart
  , unSourceName
  )

{-| @Backend.Emit.Site — one refusal site, flattened for the C table. -}
data Site = Site
  { siteFile :: !Text
  , siteLine :: !Int
  , siteColumn :: !Int
  , siteCode :: !Text
  , siteMessage :: !Text
  , siteHelp :: !(Maybe Text)
  , siteLineText :: !Text
  , siteIndent :: !Int
  , siteWidth :: !Int
  , siteMultiline :: !Bool
  , siteHasExcerpt :: !Bool
  }
  deriving stock (Eq, Show)

{-| @Backend.Emit.State — output lines (reversed), sites (reversed), and the
    deterministic counters that name temporaries and index sites. -}
data EmitState = EmitState
  { emitOutput :: ![Text]
  , emitSites :: ![Site]
  , emitNextSite :: !Int
  , emitNextTemp :: !Int
  , emitIndent :: !Int
  , emitSources :: ![Source]
  }

emptyEmitState :: [Source] -> EmitState
emptyEmitState sources =
  EmitState
    { emitOutput = []
    , emitSites = []
    , emitNextSite = 0
    , emitNextTemp = 0
    , emitIndent = 0
    , emitSources = sources
    }

{-| Emit the whole translation unit. -}
emitProgram :: Text -> [Source] -> CoreModule -> Text
emitProgram version sources coreModule =
  Text.unlines (header <> runtime <> table <> program)
 where
  header =
    [ "/* Generated by pudu " <> version <> " from module " <> coreModuleName coreModule <> ". Do not edit. */"
    , ""
    ]
  runtime = concatMap selectPart runtimeParts
  needs = runtimeNeeds coreModule
  selectPart part
    | Set.member (runtimePartName part) needs = runtimePartLines part <> [""]
    | otherwise = []
  state = foldl' emitFunction (emptyEmitState sources) (coreModuleFunctions coreModule)
  table = renderSites (reverse (emitSites state))
  program =
    reverse (emitOutput state)
      <> [ ""
         , "int main(void) {"
         , "  int64_t pudu_result = pudu_fn_main();"
         , "  return pudu_status(pudu_result);"
         , "}"
         ]

line :: EmitState -> Text -> EmitState
line state text =
  state{emitOutput = (Text.replicate (emitIndent state) " " <> text) : emitOutput state}

{-| Which runtime parts the module's operations call. The walk reads the same
    shapes emission emits: every checked operation reaches `pudu_fail` through
    its site, every print reaches exactly one print helper, and the prelude and
    the status clamp are always written. A part that is not selected is not
    written at all, because an unused `static inline` helper is a
    `-Wunused-function` warning, and a native build must be warning-free. -}
runtimeNeeds :: CoreModule -> Set.Set Text
runtimeNeeds coreModule = foldl' needFunction base (coreModuleFunctions coreModule)
 where
  base = Set.fromList ["prelude", "status"]

needFunction :: Set.Set Text -> CoreFunction -> Set.Set Text
needFunction needs function = needBlock needs (coreFunctionBody function)

needBlock :: Set.Set Text -> CoreBlock -> Set.Set Text
needBlock needs block =
  let afterStatements = foldl' needStatement needs (coreBlockStatements block)
   in case coreBlockResult block of
        Nothing -> afterStatements
        Just expression -> needExpression afterStatements expression

needStatement :: Set.Set Text -> CoreStatement -> Set.Set Text
needStatement needs statement = case coreStatementShape statement of
  CoreDeclare _ expression -> needExpression needs expression
  CoreAssign _ expression -> needExpression needs expression
  CoreEvaluate expression -> needExpression needs expression
  CoreWhile condition body -> needBlock (needExpression needs condition) body
  CoreIf condition thenBlock elseExpression ->
    let afterCondition = needExpression needs condition
        afterThen = needBlock afterCondition thenBlock
     in case elseExpression of
          Nothing -> afterThen
          Just expression -> needExpression afterThen expression
  CoreReturn result -> case result of
    Nothing -> needs
    Just expression -> needExpression needs expression

needExpression :: Set.Set Text -> CoreExpression -> Set.Set Text
needExpression needs expression = case coreExpressionShape expression of
  CoreIntegerLiteral _ _ -> needs
  CoreBoolLiteral _ -> needs
  CoreTextLiteral _ -> needs
  CoreReadLocal _ -> needs
  CoreNegate operand -> needExpression (checked "neg" needs) operand
  CoreNot operand -> needExpression needs operand
  CoreBinary operator left right ->
    let withOperator = case operator of
          CoreAdd -> checked "add" needs
          CoreSubtract -> checked "sub" needs
          CoreMultiply -> checked "mul" needs
          CoreDivide -> checked "div" needs
          CoreRemainder -> checked "rem" needs
          _ -> needs
     in needExpression (needExpression withOperator left) right
  CoreDisplay operand -> needExpression needs operand
  CorePrint argument ->
    needExpression (Set.insert (printerFor argument) needs) argument
  CoreBlockValue block -> needBlock needs block
  CoreIfValue condition thenBlock elseExpression ->
    needExpression (needBlock (needExpression needs condition) thenBlock) elseExpression

{-| A checked operation's helper, the site record it points at, and the
    refusal renderer it calls. -}
checked :: Text -> Set.Set Text -> Set.Set Text
checked part needs =
  Set.insert "site" (Set.insert "colored" (Set.insert "fail" (Set.insert part needs)))

{-| The print helper a print reaches. Lowering admits only a text literal or a
    display of Int or Bool as a print argument, which is what emission emits,
    so the walk reads the same shapes. -}
printerFor :: CoreExpression -> Text
printerFor argument = case coreExpressionShape argument of
  CoreDisplay inner -> case coreExpressionType inner of
    CoreBoolType -> "print_bool"
    _ -> "print_int"
  _ -> "print_str"

{-| Run an emission while collecting the lines it wrote, so a loop condition
    that needs temporaries can be placed inside the loop instead of before it. -}
capture :: EmitState -> CoreExpression -> (EmitState, [Text], Text)
capture state expression =
  let (after, text) = emitExpression state{emitOutput = []} expression
   in (after{emitOutput = emitOutput state}, reverse (emitOutput after), text)

freshTemp :: EmitState -> (EmitState, Text)
freshTemp state =
  (state{emitNextTemp = emitNextTemp state + 1}, "pudu_t" <> textOfInt (emitNextTemp state))

textOfInt :: Int -> Text
textOfInt = Text.pack . show

{-| Bake a site for a span: location and excerpt geometry from the program's
    own source, text from the caller. -}
siteAt :: EmitState -> Span -> Text -> Text -> Maybe Text -> (EmitState, Int)
siteAt state spanValue code message help =
  (state{emitSites = site : emitSites state, emitNextSite = emitNextSite state + 1}, emitNextSite state)
 where
  source = case filter ((== spanSource spanValue) . sourceName) (emitSources state) of
    found : _ -> Just found
    [] -> Nothing
  position = source >>= \found -> offsetPosition found (spanStart spanValue)
  excerpt = source >>= \found -> excerptGeometry found spanValue
  site =
    Site
      { siteFile = unSourceName (spanSource spanValue)
      , siteLine = maybe 1 positionLine position
      , siteColumn = maybe 1 positionColumn position
      , siteCode = code
      , siteMessage = message
      , siteHelp = help
      , siteLineText = maybe Text.empty excerptLineText excerpt
      , siteIndent = maybe 0 excerptIndent excerpt
      , siteWidth = maybe 1 excerptWidth excerpt
      , siteMultiline = maybe False excerptMultiline excerpt
      , siteHasExcerpt = case excerpt of
          Just _ -> True
          Nothing -> False
      }

overflowSite :: EmitState -> Span -> IntegerKind -> CheckedOperation -> (EmitState, Int)
overflowSite state spanValue kind operation =
  siteAt state spanValue overflowCode (overflowMessage kind operation) (Just overflowHelp)

divideByZeroSite :: EmitState -> Span -> (EmitState, Int)
divideByZeroSite state spanValue =
  siteAt state spanValue divideByZeroCode divideByZeroMessage Nothing

renderSites :: [Site] -> [Text]
renderSites [] = []
renderSites sites =
  ["static const pudu_site pudu_sites[] = {"]
    <> map renderSite sites
    <> ["};", ""]
 where
  renderSite site =
    "  { "
      <> cString (siteFile site)
      <> ", "
      <> textOfInt (siteLine site)
      <> ", "
      <> textOfInt (siteColumn site)
      <> ", "
      <> cString (siteCode site)
      <> ", "
      <> cString (siteMessage site)
      <> ", "
      <> maybe "NULL" cString (siteHelp site)
      <> ", "
      <> cString (siteLineText site)
      <> ", "
      <> textOfInt (siteIndent site)
      <> ", "
      <> textOfInt (siteWidth site)
      <> ", "
      <> flag (siteMultiline site)
      <> ", "
      <> flag (siteHasExcerpt site)
      <> " },"
  flag True = "1"
  flag False = "0"

{-| A C string literal for exact bytes: printable ASCII verbatim, everything
    else as a three-digit octal escape, so any byte survives any compiler and
    no escape can run into the next character. -}
cString :: Text -> Text
cString text = "\"" <> Text.concat (map escapeByte (ByteString.unpack (Text.encodeUtf8 text))) <> "\""
 where
  escapeByte byte
    | byte == 0x22 = "\\\""
    | byte == 0x5C = "\\\\"
    | byte >= 0x20 && byte <= 0x7E = Text.singleton (toEnum (fromIntegral byte))
    | otherwise = "\\" <> octal byte
  octal byte =
    let digits = [byte `div` 64, (byte `mod` 64) `div` 8, byte `mod` 8]
     in Text.pack (map (toEnum . (+ ord '0') . fromIntegral) digits)

cStringBytes :: Text -> Int
cStringBytes = ByteString.length . Text.encodeUtf8

emitFunction :: EmitState -> CoreFunction -> EmitState
emitFunction state function =
  line (line afterBody returnText) "}"
 where
  opened = line state ("static int64_t " <> functionSymbol function <> "(void) {")
  inner = opened{emitIndent = emitIndent state + 1}
  (afterBody, returnText) = case coreFunctionResult function of
    CoreIntegerType _ ->
      let (afterTemp, temp) = freshTemp inner
          declared = line afterTemp ("int64_t " <> temp <> ";")
          filled = emitBlockInto declared (Just temp) (coreFunctionBody function)
       in (filled, "return " <> temp <> ";")
    _ -> (emitBlockInto inner Nothing (coreFunctionBody function), "return 0;")

functionSymbol :: CoreFunction -> Text
functionSymbol function = "pudu_fn_" <> sanitize (coreFunctionName function)
 where
  sanitize = Text.map keep
  keep character
    | character `elem` (['a' .. 'z'] <> ['A' .. 'Z'] <> ['0' .. '9'] <> "_") = character
    | otherwise = '_'

{-| Emit a block's statements and result at one indent deeper than the state
    it is given. A `Just temp` assigns the block's value to the temp;
    `Nothing` evaluates it and throws it away, because a discarded checked
    expression can still refuse. -}
emitBlockInto :: EmitState -> Maybe Text -> CoreBlock -> EmitState
emitBlockInto state target block =
  let inner = state{emitIndent = emitIndent state + 1}
      afterStatements = foldl' emitStatement inner (coreBlockStatements block)
   in case coreBlockResult block of
        Nothing -> afterStatements
        Just expression -> case target of
          Just temp -> emitAssign afterStatements temp expression
          Nothing -> emitDiscard afterStatements expression

emitAssign :: EmitState -> Text -> CoreExpression -> EmitState
emitAssign state temp expression = case coreExpressionType expression of
  CoreUnitType -> emitDiscard state expression
  CoreTextType -> emitDiscard state expression
  _ ->
    let (after, text) = emitExpression state expression
     in line after (temp <> " = " <> text <> ";")

emitDiscard :: EmitState -> CoreExpression -> EmitState
emitDiscard state expression = case coreExpressionType expression of
  CoreTextType -> emitEffects state expression
  CoreUnitType -> emitEffects state expression
  _ ->
    let (after, text) = emitExpression state expression
     in line after ("(void)(" <> text <> ");")

{-| Discard a text or unit value, which has no C representation of its own:
    only what its parts do is observable, so emit exactly that. -}
emitEffects :: EmitState -> CoreExpression -> EmitState
emitEffects state expression = case coreExpressionShape expression of
  CoreTextLiteral _ -> state
  CoreDisplay inner -> emitDiscard state inner
  CorePrint _ ->
    let (after, text) = emitExpression state expression
     in line after (text <> ";")
  CoreBlockValue block -> emitBlockInto state Nothing block
  CoreIfValue condition thenBlock elseExpression -> emitIf state condition thenBlock (Just elseExpression)
  _ -> invariant "a discarded value with no effects"

emitStatement :: EmitState -> CoreStatement -> EmitState
emitStatement state statement = case coreStatementShape statement of
  CoreDeclare local expression ->
    let (after, text) = emitExpression state expression
     in line after (declaration local <> " = " <> text <> "; " <> comment local)
  CoreAssign local expression ->
    let (after, text) = emitExpression state expression
     in line after (localSymbol local <> " = " <> text <> ";")
  CoreEvaluate expression -> emitDiscard state expression
  CoreWhile condition body -> emitWhile state condition body
  CoreIf condition thenBlock elseExpression -> emitIf state condition thenBlock elseExpression
  CoreReturn Nothing -> line state "return 0;"
  CoreReturn (Just expression) -> case coreExpressionType expression of
    CoreUnitType -> line (emitDiscard state expression) "return 0;"
    _ ->
      let (after, text) = emitExpression state expression
       in line after ("return " <> text <> ";")

emitWhile :: EmitState -> CoreExpression -> CoreBlock -> EmitState
emitWhile state condition body =
  let (afterCondition, prelude, conditionText) = capture state condition
   in if null prelude
        then
          let opened = line afterCondition ("while (" <> conditionText <> ") {")
              filled = emitBlockInto opened Nothing body
           in line filled "}"
        else
          let opened = line afterCondition "while (1) {"
              inside = opened{emitIndent = emitIndent afterCondition + 1}
              withPrelude = foldl' (\current text -> line current text) inside prelude
              guarded = line withPrelude ("if (!(" <> conditionText <> ")) break;")
              filled = emitBlockInto guarded{emitIndent = emitIndent afterCondition} Nothing body
           in line filled "}"

emitIf :: EmitState -> CoreExpression -> CoreBlock -> Maybe CoreExpression -> EmitState
emitIf state condition thenBlock elseExpression =
  let (afterCondition, conditionText) = emitExpression state condition
      opened = line afterCondition ("if (" <> conditionText <> ") {")
      filledThen = emitBlockInto opened Nothing thenBlock
   in case elseExpression of
        Nothing -> line filledThen "}"
        Just expression -> case coreExpressionShape expression of
          CoreIfValue nestedCondition nestedThen nestedElse ->
            let openedElse = line filledThen "} else {"
                inner = openedElse{emitIndent = emitIndent filledThen + 1}
                nested = emitIf inner nestedCondition nestedThen (Just nestedElse)
             in line nested{emitIndent = emitIndent filledThen} "}"
          _ ->
            let openedElse = line filledThen "} else {"
                inner = openedElse{emitIndent = emitIndent filledThen + 1}
             in line (emitDiscard inner expression) "}"

emitExpression :: EmitState -> CoreExpression -> (EmitState, Text)
emitExpression state expression = case coreExpressionShape expression of
  CoreIntegerLiteral kind number -> (state, integerLiteralText kind number)
  CoreBoolLiteral flag -> (state, if flag then "1" else "0")
  CoreReadLocal local -> (state, localSymbol local)
  CoreNegate operand ->
    let (afterOperand, operandText) = emitExpression state operand
        (afterSite, index) = overflowSite afterOperand (coreExpressionSpan expression) kindOf CheckedNegate
     in (afterSite, "pudu_neg(" <> operandText <> ", &pudu_sites[" <> textOfInt index <> "])")
   where
    kindOf = integerKindOfExpression expression
  CoreNot operand ->
    let (afterOperand, operandText) = emitExpression state operand
     in (afterOperand, "(!(" <> operandText <> "))")
  CoreBinary operator left right -> emitBinary state expression operator left right
  CoreTextLiteral text -> (state, cString text)
  CoreDisplay _ -> invariant "a display outside a print"
  CorePrint argument -> emitPrint state argument
  CoreBlockValue block -> case coreExpressionType expression of
    CoreUnitType -> (emitBlockInto state Nothing block, "0")
    CoreTextType -> (emitBlockInto state Nothing block, "0")
    resultType ->
      let (afterTemp, temp) = freshTemp state
          declared = line afterTemp (declarationFor resultType temp <> ";")
          filled = emitBlockInto declared (Just temp) block
       in (filled, temp)
  CoreIfValue condition thenBlock elseExpression -> case coreExpressionType expression of
    CoreUnitType -> (emitIf state condition thenBlock (Just elseExpression), "0")
    CoreTextType -> (emitIf state condition thenBlock (Just elseExpression), "0")
    resultType ->
      let (afterTemp, temp) = freshTemp state
          declared = line afterTemp (declarationFor resultType temp <> ";")
          filled = emitIfValueInto declared temp condition thenBlock elseExpression
       in (filled, temp)

emitPrint :: EmitState -> CoreExpression -> (EmitState, Text)
emitPrint state argument = case coreExpressionShape argument of
  CoreTextLiteral text ->
    ( state
    , "pudu_print_str(" <> cString text <> ", " <> textOfInt (cStringBytes text) <> ")"
    )
  CoreDisplay inner -> case coreExpressionType inner of
    CoreIntegerType _ ->
      let (after, text) = emitExpression state inner
       in (after, "pudu_print_int(" <> text <> ")")
    CoreBoolType ->
      let (after, text) = emitExpression state inner
       in (after, "pudu_print_bool(" <> text <> ")")
    _ -> invariant "print(display(...)) of a value that is neither Int nor Bool"
  _ -> invariant "print of a text value that is not a literal or a display"

emitIfValueInto :: EmitState -> Text -> CoreExpression -> CoreBlock -> CoreExpression -> EmitState
emitIfValueInto state temp condition thenBlock elseExpression =
  let (afterCondition, conditionText) = emitExpression state condition
      opened = line afterCondition ("if (" <> conditionText <> ") {")
      filledThen = emitBlockInto opened (Just temp) thenBlock
      openedElse = line filledThen "} else {"
      inner = openedElse{emitIndent = emitIndent state + 1}
      filledElse = emitElseInto inner temp elseExpression
   in line filledElse{emitIndent = emitIndent state} "}"

emitElseInto :: EmitState -> Text -> CoreExpression -> EmitState
emitElseInto state temp expression = case coreExpressionShape expression of
  CoreBlockValue block -> emitBlockInto state (Just temp) block
  CoreIfValue nestedCondition nestedThen nestedElse ->
    emitIfValueInto state temp nestedCondition nestedThen nestedElse
  _ -> case coreExpressionType expression of
    CoreUnitType -> emitDiscard state expression
    _ -> emitAssign state temp expression

emitBinary :: EmitState -> CoreExpression -> CoreBinaryOperator -> CoreExpression -> CoreExpression -> (EmitState, Text)
emitBinary state expression operator left right = case operator of
  CoreAdd -> checkedCall "pudu_add" CheckedAdd
  CoreSubtract -> checkedCall "pudu_sub" CheckedSubtract
  CoreMultiply -> checkedCall "pudu_mul" CheckedMultiply
  CoreDivide ->
    let (afterLeft, leftText) = emitExpression state left
        (afterRight, rightText) = emitExpression afterLeft right
        (afterZero, zeroIndex) = divideByZeroSite afterRight (coreExpressionSpan expression)
        (afterOverflow, overflowIndex) = overflowSite afterZero (coreExpressionSpan expression) kindOf CheckedDivide
     in ( afterOverflow
        , "pudu_div("
            <> leftText
            <> ", "
            <> rightText
            <> ", &pudu_sites["
            <> textOfInt zeroIndex
            <> "], &pudu_sites["
            <> textOfInt overflowIndex
            <> "])"
        )
  CoreRemainder ->
    let (afterLeft, leftText) = emitExpression state left
        (afterRight, rightText) = emitExpression afterLeft right
        (afterZero, zeroIndex) = divideByZeroSite afterRight (coreExpressionSpan expression)
     in (afterZero, "pudu_rem(" <> leftText <> ", " <> rightText <> ", &pudu_sites[" <> textOfInt zeroIndex <> "])")
  CoreLess -> comparison "<"
  CoreLessOrEqual -> comparison "<="
  CoreGreater -> comparison ">"
  CoreGreaterOrEqual -> comparison ">="
  CoreEqual -> comparison "=="
  CoreNotEqual -> comparison "!="
  CoreAnd -> plain "&&"
  CoreOr -> plain "||"
 where
  kindOf = integerKindOfExpression expression
  checkedCall helper operation =
    let (afterLeft, leftText) = emitExpression state left
        (afterRight, rightText) = emitExpression afterLeft right
        (afterSite, index) = overflowSite afterRight (coreExpressionSpan expression) kindOf operation
     in (afterSite, helper <> "(" <> leftText <> ", " <> rightText <> ", &pudu_sites[" <> textOfInt index <> "])")
  plain operatorText =
    let (afterLeft, leftText) = emitExpression state left
        (afterRight, rightText) = emitExpression afterLeft right
     in (afterRight, "(" <> leftText <> " " <> operatorText <> " " <> rightText <> ")")
  {-| Comparisons are written without their own parentheses: C's precedence
      already binds them tighter than `&&` and `||`, and a condition of the
      form `if ((a == b))` draws `-Wparentheses-equality`, which the
      warning-free contract does not allow. -}
  comparison operatorText =
    let (afterLeft, leftText) = emitExpression state left
        (afterRight, rightText) = emitExpression afterLeft right
     in (afterRight, leftText <> " " <> operatorText <> " " <> rightText)

integerKindOfExpression :: CoreExpression -> IntegerKind
integerKindOfExpression expression = case coreExpressionType expression of
  CoreIntegerType kind -> kind
  _ -> PlatformSigned

integerLiteralText :: IntegerKind -> Integer -> Text
integerLiteralText _ number
  | number == toInteger (minBound :: Int64) = "INT64_MIN"
  | otherwise = "(int64_t)" <> textOfInteger number <> "LL"

textOfInteger :: Integer -> Text
textOfInteger = Text.pack . show

declaration :: CoreLocal -> Text
declaration local = declarationFor (coreLocalType local) (localSymbol local)

declarationFor :: CoreType -> Text -> Text
declarationFor coreType name = case coreType of
  CoreIntegerType _ -> "int64_t " <> name
  CoreBoolType -> "int " <> name
  CoreTextType -> "const char *" <> name
  CoreUnitType -> "int " <> name

localSymbol :: CoreLocal -> Text
localSymbol local = "pudu_v" <> textOfInt (coreLocalId local)

comment :: CoreLocal -> Text
comment local = "/* " <> coreLocalName local <> " */"

invariant :: Text -> a
invariant reason = error ("Pudu.Backend.Emit: " <> Text.unpack reason)
